        const d2 = H.sec(-0.46); H.vfin('Fins', [[-0.42, d2.y + d2.h - 0.01], [-0.44, d2.y + d2.h + 0.06], [-0.5, d2.y + d2.h + 0.03], [-0.52, d2.y + d2.h - 0.01]]);
        const a1 = H.sec(-0.2); H.vfin('Fins', [[-0.14, a1.y - a1.h + 0.01], [-0.19, a1.y - a1.h - 0.1], [-0.27, a1.y - a1.h - 0.06], [-0.3, a1.y - a1.h + 0.01]]);
        const a2 = H.sec(-0.46); H.vfin('Fins', [[-0.42, a2.y - a2.h + 0.01], [-0.45, a2.y - a2.h - 0.05], [-0.5, a2.y - a2.h - 0.03], [-0.52, a2.y - a2.h + 0.01]]);
